#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

class Solution {
public:
    int visiblePoints(vector<vector<int>>& points, int angle, vector<int>& location) {
        int lx = location[0], ly = location[1];
        int same = 0;
        vector<double> angles;
        const double PI = acos(-1.0);
        for (const auto& p : points) {
            if (p[0] == lx && p[1] == ly) {
                same++;
            } else {
                angles.push_back(atan2(p[1] - ly, p[0] - lx) * 180.0 / PI);
            }
        }
        sort(angles.begin(), angles.end());
        int n = angles.size();
        for (int i = 0; i < n; ++i) {
            angles.push_back(angles[i] + 360.0);
        }
        int max_visible = 0;
        int left = 0;
        for (int right = 0; right < (int)angles.size(); ++right) {
            while (angles[right] - angles[left] > angle) {
                left++;
            }
            max_visible = max(max_visible, right - left + 1);
        }
        return same + max_visible;
    }
};

import java.util.*;

class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        int lx = location.get(0), ly = location.get(1);
        int same = 0;
        List<Double> angles = new ArrayList<>();
        for (List<Integer> p : points) {
            int px = p.get(0), py = p.get(1);
            if (px == lx && py == ly) {
                same++;
            } else {
                angles.add(Math.toDegrees(Math.atan2(py - ly, px - lx)));
            }
        }
        Collections.sort(angles);
        int n = angles.size();
        for (int i = 0; i < n; ++i) {
            angles.add(angles.get(i) + 360.0);
        }
        int maxVisible = 0;
        int left = 0;
        for (int right = 0; right < angles.size(); ++right) {
            while (angles.get(right) - angles.get(left) > angle) {
                left++;
            }
            maxVisible = Math.max(maxVisible, right - left + 1);
        }
        return same + maxVisible;
    }
}

